// Tauri host adapter. Runs before the bundle's js/main.js. It builds the shared
// consent broker from descriptor.json and replaces window.fetch so that every
// cross-origin request must match a declared operation and be approved by the
// user in the trusted consent dialog. Undeclared requests fail closed; there is
// no silent fallback to the raw network.
import {
  clientEndpointAllowsRequest, createClientConsentHost, createClientOperationBroker,
} from "./runtime.js";
// Generated by scripts/build.mjs next to descriptor.json. No top-level await, so
// this module finishes evaluating before the bundle's own module script runs.
import descriptor from "./descriptor.js";
import { safeId } from "./bot-domain.js";
const capabilities = [...new Set(descriptor.operations.map((op) => op.capability))];
const selectors = descriptor.operations.map((op) => [op.capability, op.service, op.operation]);
const broker = createClientOperationBroker({
  runtime: descriptor,
  requestedCapabilities: capabilities,
  // The shell accepts the declaration; each invocation still needs its own
  // direct user choice in the consent dialog. App code cannot mint approval.
  approvedOperations: descriptor.operations,
  hostSupportedOperations: selectors,
  consentHost: createClientConsentHost(),
});

const appFetch = globalThis.fetch.bind(globalThis);
const hasRawTraversal = (rawUrl) => {
  const pathPart = rawUrl
    .replace(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/[^/?#]*/u, "")
    .replace(/^\/\/[^/?#]*/u, "")
    .split(/[?#]/u)[0];
  return /(?:^|\/)\.\.?(?:\/|$)/u.test(pathPart)
    || pathPart.includes("\\")
    || /%2e|%2f|%5c/iu.test(pathPart);
};
// Enforce the app's stricter safeId rule at the host boundary for every
// parameterized route segment (e.g. :bot_id on read-activity) before consent
// or broker processing, independent of page URL builders.
const routeParamsSatisfySafeId = (endpoint, pathname, method) => {
  const routes = Array.isArray(endpoint?.routes)
    ? endpoint.routes
    : (typeof endpoint?.path === "string" ? [{ method: endpoint.method, path: endpoint.path }] : []);
  const actual = pathname === "/" ? [] : pathname.slice(1).split("/");
  return routes.some((route) => {
    if (route.method !== method) return false;
    if (typeof route.path !== "string") return true;
    const expected = route.path === "/" ? [] : route.path.slice(1).split("/");
    if (expected.length !== actual.length) return false;
    return expected.every((segment, index) => (
      segment.startsWith(":") ? safeId(actual[index]) : segment === actual[index]
    ));
  });
};
globalThis.fetch = function guardedFetch(input, init) {
  const rawUrl = input instanceof Request ? input.url : String(input);
  let url;
  try {
    url = new URL(rawUrl, location.href);
  } catch {
    return Promise.reject(new TypeError("不正な URL のため送信しません。"));
  }
  if (url.username || url.password) {
    return Promise.reject(new TypeError("認証情報を含む URL は送信しません。"));
  }
  const method = String(init?.method ?? (input instanceof Request ? input.method : "GET")).toUpperCase();
  if (url.origin === location.origin) return appFetch(input, init);
  if (hasRawTraversal(rawUrl)) {
    return Promise.reject(new TypeError("パス正規化やトラバーサルを含む接続先は送信しません。"));
  }
  const operation = descriptor.operations.find((op) => (
    clientEndpointAllowsRequest(op.endpoint, url.href, method)
    && routeParamsSatisfySafeId(op.endpoint, url.pathname, method)
  ));
  if (!operation) return Promise.reject(new TypeError("この接続先・操作は宣言されていないため送信しません。"));
  const selector = { capability: operation.capability, service: operation.service, operation: operation.operation };
  return broker.invoke(selector, { input: url.href, init: { ...init, method } }, { signal: init?.signal ?? undefined });
};

// Links that leave the app origin are not followed: no silent navigation or network use.
// A declared external operation must go through the consent broker above instead.
document.addEventListener("click", (event) => {
  const anchor = event.target?.closest?.("a[href]");
  if (!anchor) return;
  let target;
  try {
    target = new URL(anchor.getAttribute("href"), location.href);
  } catch {
    event.preventDefault();
    return;
  }
  if (target.origin !== location.origin) event.preventDefault();
}, true);
